sets_out = []
cards_out = []
seen_ids = set()

for set_id, name, emoji, active_in_review, phrases in CURRICULUM:
    assert set_id not in seen_ids, f"Duplicate set id {set_id}"
    seen_ids.add(set_id)
    sets_out.append({
        "id": set_id,
        "name": name,
        "emoji": emoji,
        "includeInReview": active_in_review,
        "createdAt": 1750000000000,
    })
    for idx, (thai, english, roman, breakdown) in enumerate(phrases, start=1):
        card_id = f"{set_id}-c{idx:02d}"
        assert thai.strip() and english.strip() and roman.strip(), f"Blank field in {card_id}"
        assert len(breakdown) >= 1, f"Empty breakdown in {card_id}"
        cards_out.append({
            "id": card_id,
            "setId": set_id,
            "thai": thai.strip(),
            "english": english.strip(),
            "romanization": roman.strip(),
            "wordBreakdown": [
                {"thai": w, "english": g, "romanization": r}
                for (w, g, r) in breakdown
            ],
            "rating": "NEW",
            "stabilityDays": 0.5,
            "difficulty": 5.0,
            "badCount": 0,
            "okCount": 0,
            "goodCount": 0,
            "streak": 0,
            "lastReviewedAt": 0,
            "nextReviewAt": 0,
            "createdAt": 1750000000000 + idx,
        })

out_path = r"C:\Users\Jordan\AndroidStudioProjects\ThaiFlash\app\src\main\assets\thai_curriculum_17_sets.json"
os.makedirs(os.path.dirname(out_path), exist_ok=True)
with open(out_path, "w", encoding="utf-8") as f:
    json.dump({"sets": sets_out, "cards": cards_out}, f, ensure_ascii=False, indent=2)

unique_words = {
    item["thai"]
    for c in cards_out
    for item in c["wordBreakdown"]
}
print(f"Generated {len(sets_out)} sets, {len(cards_out)} phrases, {len(unique_words)} unique Thai word chunks -> {out_path}")
